import "server-only";
import type { Prisma } from "@/generated/prisma/client";

// Money-moving building blocks. Every function takes the caller's transaction:
// they are only correct inside one that has already called lockLease().
//
// Lock order (the same everywhere, so two transactions never deadlock):
//   1. the lease row (lockLease)            — serializes all money on a lease
//   2. the payment row, if any (FOR UPDATE)
//   3. invoice/payment rows touched by the allocation trigger (FOR NO KEY UPDATE)

export type Tx = Prisma.TransactionClient;

export type LeaseTotals = {
  invoicedSen: bigint;
  allocatedSen: bigint;
  pendingSen: bigint;
};

export type AuditEntry = {
  orgId: string;
  actorId: string | null;
  action: string;
  entityId: string | null;
  details: Prisma.InputJsonObject;
};

type UnpaidInvoiceRow = { id: string; unpaid_sen: bigint };
type TotalsRow = { invoiced: bigint; allocated: bigint; pending: bigint };

/**
 * Takes the lease row lock. Every money-moving transaction on a lease calls
 * this FIRST, so cap checks, approvals, voids and webhook settlements on one
 * lease run one at a time and each sees the previous one's committed rows.
 * Returns false if the lease does not exist.
 */
export const lockLease = async (tx: Tx, leaseId: string): Promise<boolean> => {
  const rows = await tx.$queryRaw<{ id: string }[]>`
    SELECT id FROM public.leases WHERE id = ${leaseId}::uuid FOR UPDATE`;
  return rows.length > 0;
};

/** Sums for the cap: total invoiced, total allocated, total still pending_verification. */
export const leaseTotals = async (
  tx: Tx,
  leaseId: string,
): Promise<LeaseTotals> => {
  const rows = await tx.$queryRaw<TotalsRow[]>`
    SELECT
      (SELECT coalesce(sum(i.amount_sen), 0)::bigint
         FROM public.invoices i
        WHERE i.lease_id = ${leaseId}::uuid) AS invoiced,
      (SELECT coalesce(sum(a.amount_sen), 0)::bigint
         FROM public.payment_allocations a
         JOIN public.invoices i ON i.id = a.invoice_id
        WHERE i.lease_id = ${leaseId}::uuid) AS allocated,
      (SELECT coalesce(sum(p.amount_sen), 0)::bigint
         FROM public.payments p
        WHERE p.lease_id = ${leaseId}::uuid
          AND p.status = 'pending_verification') AS pending`;
  const row = rows[0];
  if (!row) {
    throw new Error("leaseTotals returned no row");
  }
  return {
    invoicedSen: BigInt(row.invoiced),
    allocatedSen: BigInt(row.allocated),
    pendingSen: BigInt(row.pending),
  };
};

/**
 * Allocates an approved payment to its lease's invoices that still have
 * something unpaid, in allocation order (due date, deposit before rent, period
 * index), filling each before the next — including invoices not due yet.
 * Whatever is left is stored as unapplied_sen. Caller holds the lease lock.
 */
export const allocatePayment = async (
  tx: Tx,
  paymentId: string,
): Promise<void> => {
  const payment = await tx.payments.findUnique({
    where: { id: paymentId },
    select: {
      id: true,
      org_id: true,
      lease_id: true,
      amount_sen: true,
      status: true,
      _count: { select: { payment_allocations: true } },
    },
  });
  if (!payment) {
    throw new Error(`Payment ${paymentId} not found`);
  }
  if (payment.status !== "approved") {
    throw new Error(`Payment ${paymentId} is ${payment.status}, not approved`);
  }
  if (payment._count.payment_allocations > 0) {
    throw new Error(`Payment ${paymentId} is already allocated`);
  }

  const invoices = await tx.$queryRaw<UnpaidInvoiceRow[]>`
    SELECT i.id,
           (i.amount_sen - coalesce(sum(a.amount_sen), 0))::bigint AS unpaid_sen
      FROM public.invoices i
      LEFT JOIN public.payment_allocations a ON a.invoice_id = i.id
     WHERE i.lease_id = ${payment.lease_id}::uuid
     GROUP BY i.id
    HAVING i.amount_sen - coalesce(sum(a.amount_sen), 0) > 0
     ORDER BY i.due_date, (i.kind = 'deposit') DESC, i.period_index, i.id`;

  let remaining = payment.amount_sen;
  const allocations: Prisma.payment_allocationsCreateManyInput[] = [];
  for (const invoice of invoices) {
    if (remaining <= 0n) {
      break;
    }
    const unpaid = BigInt(invoice.unpaid_sen);
    const amount = remaining < unpaid ? remaining : unpaid;
    allocations.push({
      org_id: payment.org_id,
      payment_id: payment.id,
      invoice_id: invoice.id,
      amount_sen: amount,
    });
    remaining -= amount;
  }

  if (allocations.length > 0) {
    await tx.payment_allocations.createMany({ data: allocations });
  }
  if (remaining > 0n) {
    await tx.payments.update({
      where: { id: payment.id },
      data: { unapplied_sen: remaining },
    });
  }
};

/** Appends one audit_log row (append-only table) inside the caller's transaction. */
export const writeAudit = async (tx: Tx, entry: AuditEntry): Promise<void> => {
  await tx.audit_log.create({
    data: {
      org_id: entry.orgId,
      actor_id: entry.actorId,
      action: entry.action,
      entity_id: entry.entityId,
      details: entry.details,
    },
  });
};
import "server-only";
import { z } from "zod";
import type { payments } from "@/generated/prisma/client";
import { toSafeNumber } from "@/lib/money";
import {
  requireManager,
  requireMember,
  requireVisibleLease,
  requireVisiblePayment,
} from "../access";
import {
  allocatePayment,
  leaseTotals,
  lockLease,
  writeAudit,
  type Tx,
} from "../allocation";
import type { Actor } from "../auth";
import { pgErrorCode } from "../db-errors";
import { badRequest, conflict, notFound, unprocessable } from "../http";
import { prisma } from "../prisma";
import { removeSlip, signedSlipUrl, uploadSlip } from "../slips";

// Manual payments (cash, bank transfer) and the manager decisions on them.
//
// Concurrency: every transaction here locks the lease row FIRST (lockLease),
// then re-reads whatever it decides on. Two staff recording at once, or two
// managers approving at once, therefore run one after the other on that
// lease, and the second sees the first's committed rows: the cap cannot be
// exceeded together and a payment cannot be approved (allocated) twice.
//
// Check order in every entry point: 404 (not visible) -> 403 (role) ->
// 400 (input) -> 409 (state) / 422 (amount). 401 is the route's job.

const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;
const TRANSACTION_OPTIONS = { maxWait: 10000, timeout: 20000 };
const FK_VIOLATION = "23503";
const UNIQUE_VIOLATION = "23505";

const recordPaymentSchema = z.object({
  amountSen: z.int().positive(),
  method: z.enum(["cash", "bank_transfer"]),
  // ISO 8601 with an explicit offset (Z or ±hh:mm); a bare local time is
  // ambiguous on a UTC server, so it is refused rather than guessed.
  receivedAt: z.union([z.iso.datetime({ offset: true }), z.date()]),
  slipPath: z.string().min(1).optional(),
});

const reasonSchema = z.object({
  reason: z.string().trim().min(5, "Reason must be at least 5 characters"),
});

export type RecordPaymentInput = z.input<typeof recordPaymentSchema>;
export type ReasonInput = z.input<typeof reasonSchema>;
export type PaymentStatus =
  "pending_verification" | "approved" | "rejected" | "voided";
export type RecordPaymentResult = { id: string; status: PaymentStatus };
export type DecisionResult = { status: PaymentStatus };
export type SlipInput = Omit<RecordPaymentInput, "slipPath" | "method"> & {
  method: "cash" | "bank_transfer";
};

const toInstant = (value: string | Date): Date => {
  const instant = typeof value === "string" ? new Date(value) : value;
  if (Number.isNaN(instant.getTime())) {
    throw badRequest("receivedAt: Invalid date-time");
  }
  return instant;
};

// Re-reads the payment under a row lock, after the lease lock is held.
const lockPayment = async (tx: Tx, paymentId: string): Promise<payments> => {
  await tx.$queryRaw`
    SELECT id FROM public.payments WHERE id = ${paymentId}::uuid FOR UPDATE`;
  const payment = await tx.payments.findUnique({ where: { id: paymentId } });
  if (!payment) {
    throw notFound();
  }
  return payment;
};

const asStatus = (status: string): PaymentStatus => {
  if (
    status !== "pending_verification" &&
    status !== "approved" &&
    status !== "rejected" &&
    status !== "voided"
  ) {
    throw new Error(`Unknown payment status in database: ${status}`);
  }
  return status;
};

/**
 * POST /api/leases/:leaseId/payments. Staff and managers only. A manager's
 * payment is approved (and allocated) at once; a staff payment waits as
 * pending_verification. Capped at the lease's remaining balance minus what is
 * already pending.
 */
export const recordPayment = async (
  actor: Actor,
  leaseId: string,
  input: unknown,
  now: Date = new Date(),
): Promise<RecordPaymentResult> => {
  const lease = await requireVisibleLease(actor, leaseId);
  requireMember(actor);
  const data = recordPaymentSchema.parse(input);
  const receivedAt = toInstant(data.receivedAt);
  if (receivedAt.getTime() > now.getTime() + MAX_CLOCK_SKEW_MS) {
    throw badRequest("receivedAt cannot be in the future");
  }
  if (data.method === "bank_transfer") {
    if (!data.slipPath) {
      throw badRequest("slipPath: A bank transfer needs a slip");
    }
    if (!data.slipPath.startsWith(`${lease.org_id}/`)) {
      throw badRequest("slipPath: Slip must be in the organization's folder");
    }
  } else if (data.slipPath !== undefined) {
    throw badRequest("slipPath: Only a bank transfer has a slip");
  }

  const approveNow = actor.role === "manager";
  try {
    return await prisma.$transaction(async (tx) => {
      await lockLease(tx, lease.id);
      const totals = await leaseTotals(tx, lease.id);
      const cap = totals.invoicedSen - totals.allocatedSen - totals.pendingSen;
      if (BigInt(data.amountSen) > cap) {
        throw unprocessable(
          `Amount exceeds the remaining balance (max ${cap > 0n ? cap.toString() : "0"} sen)`,
        );
      }
      const decidedAt = new Date();
      const payment = await tx.payments.create({
        data: {
          org_id: lease.org_id,
          lease_id: lease.id,
          amount_sen: BigInt(data.amountSen),
          method: data.method,
          status: approveNow ? "approved" : "pending_verification",
          received_at: receivedAt,
          slip_path: data.slipPath ?? null,
          recorded_by: actor.userId,
          decided_by: approveNow ? actor.userId : null,
          decided_at: approveNow ? decidedAt : null,
        },
        select: { id: true, status: true },
      });
      await writeAudit(tx, {
        orgId: lease.org_id,
        actorId: actor.userId,
        action: "payment.recorded",
        entityId: payment.id,
        details: {
          leaseId: lease.id,
          amountSen: data.amountSen,
          method: data.method,
          receivedAt: receivedAt.toISOString(),
          slipPath: data.slipPath ?? null,
        },
      });
      if (approveNow) {
        await allocatePayment(tx, payment.id);
        await writeAudit(tx, {
          orgId: lease.org_id,
          actorId: actor.userId,
          action: "payment.approved",
          entityId: payment.id,
          details: {
            leaseId: lease.id,
            amountSen: data.amountSen,
            onRecord: true,
          },
        });
      }
      return { id: payment.id, status: asStatus(payment.status) };
    }, TRANSACTION_OPTIONS);
  } catch (error) {
    const code = pgErrorCode(error);
    // payments_slip_exists trigger: the file is not in the bucket.
    if (code === FK_VIOLATION) {
      throw badRequest("slipPath: Slip file not found");
    }
    // payments.slip_path is unique: one slip backs one payment.
    if (code === UNIQUE_VIOLATION) {
      throw badRequest("slipPath: Slip is already used by another payment");
    }
    throw error;
  }
};

/**
 * UI path for a bank transfer: upload the slip, record the payment, and
 * remove the uploaded file if recording fails (the brief: no file is left
 * behind). Cash goes straight to recordPayment.
 */
export const recordPaymentWithSlip = async (
  actor: Actor,
  leaseId: string,
  input: SlipInput,
  slip: File | null,
): Promise<RecordPaymentResult> => {
  const lease = await requireVisibleLease(actor, leaseId);
  requireMember(actor);
  if (input.method === "cash") {
    return recordPayment(actor, lease.id, input);
  }
  if (!slip) {
    throw badRequest("slip: A bank transfer needs a slip");
  }
  const slipPath = await uploadSlip(lease.org_id, lease.id, slip);
  try {
    return await recordPayment(actor, lease.id, { ...input, slipPath });
  } catch (error) {
    await removeSlip(slipPath).catch(() => undefined);
    throw error;
  }
};

/**
 * Manager only. Re-checks the amount against the remaining balance at this
 * moment (invoiced - allocated); if it no longer fits, 422 and it stays
 * pending. Approving twice at once: the second waits on the lease lock, then
 * sees 'approved' and gets 409, so allocation happens once.
 */
export const approvePayment = async (
  actor: Actor,
  paymentId: string,
): Promise<DecisionResult> => {
  const visible = await requireVisiblePayment(actor, paymentId);
  requireManager(actor);
  return prisma.$transaction(async (tx) => {
    await lockLease(tx, visible.lease_id);
    const payment = await lockPayment(tx, visible.id);
    if (payment.status !== "pending_verification") {
      throw conflict(`Payment is ${payment.status}, not pending_verification`);
    }
    const totals = await leaseTotals(tx, payment.lease_id);
    const remaining = totals.invoicedSen - totals.allocatedSen;
    if (payment.amount_sen > remaining) {
      throw unprocessable(
        `Amount exceeds the remaining balance (${remaining > 0n ? remaining.toString() : "0"} sen)`,
      );
    }
    await tx.payments.update({
      where: { id: payment.id },
      data: {
        status: "approved",
        decided_by: actor.userId,
        decided_at: new Date(),
      },
    });
    await allocatePayment(tx, payment.id);
    await writeAudit(tx, {
      orgId: payment.org_id,
      actorId: actor.userId,
      action: "payment.approved",
      entityId: payment.id,
      details: {
        leaseId: payment.lease_id,
        amountSen: toSafeNumber(payment.amount_sen),
      },
    });
    return { status: "approved" as const };
  }, TRANSACTION_OPTIONS);
};

/** Manager only. pending_verification -> rejected, with a reason (>= 5 chars). */
export const rejectPayment = async (
  actor: Actor,
  paymentId: string,
  input: unknown,
): Promise<DecisionResult> => {
  const visible = await requireVisiblePayment(actor, paymentId);
  requireManager(actor);
  const { reason } = reasonSchema.parse(input);
  return prisma.$transaction(async (tx) => {
    await lockLease(tx, visible.lease_id);
    const payment = await lockPayment(tx, visible.id);
    if (payment.status !== "pending_verification") {
      throw conflict(`Payment is ${payment.status}, not pending_verification`);
    }
    await tx.payments.update({
      where: { id: payment.id },
      data: {
        status: "rejected",
        decision_reason: reason,
        decided_by: actor.userId,
        decided_at: new Date(),
      },
    });
    await writeAudit(tx, {
      orgId: payment.org_id,
      actorId: actor.userId,
      action: "payment.rejected",
      entityId: payment.id,
      details: { leaseId: payment.lease_id, reason },
    });
    return { status: "rejected" as const };
  }, TRANSACTION_OPTIONS);
};

/**
 * Manager only. approved -> voided, with a reason; removes this payment's
 * allocations only. Other payments are not touched and nothing is
 * re-allocated (in particular, no other payment's unapplied_sen moves in to
 * fill the reopened invoices — see DECISIONS.md).
 */
export const voidPayment = async (
  actor: Actor,
  paymentId: string,
  input: unknown,
): Promise<DecisionResult> => {
  const visible = await requireVisiblePayment(actor, paymentId);
  requireManager(actor);
  const { reason } = reasonSchema.parse(input);
  return prisma.$transaction(async (tx) => {
    await lockLease(tx, visible.lease_id);
    const payment = await lockPayment(tx, visible.id);
    if (payment.status !== "approved") {
      throw conflict(`Payment is ${payment.status}, not approved`);
    }
    // Status first: the allocation trigger only allows deletes once voided.
    await tx.payments.update({
      where: { id: payment.id },
      data: {
        status: "voided",
        decision_reason: reason,
        decided_by: actor.userId,
        decided_at: new Date(),
      },
    });
    const removed = await tx.payment_allocations.deleteMany({
      where: { payment_id: payment.id },
    });
    await writeAudit(tx, {
      orgId: payment.org_id,
      actorId: actor.userId,
      action: "payment.voided",
      entityId: payment.id,
      details: {
        leaseId: payment.lease_id,
        amountSen: toSafeNumber(payment.amount_sen),
        reason,
        allocationsRemoved: removed.count,
      },
    });
    return { status: "voided" as const };
  }, TRANSACTION_OPTIONS);
};

/**
 * A 60-second signed URL for a payment's slip. Staff and managers of the
 * payment's organization only (tenants cannot read slips: 403); null when the
 * payment has no slip.
 */
export const paymentSlipUrl = async (
  actor: Actor,
  paymentId: string,
): Promise<string | null> => {
  const payment = await requireVisiblePayment(actor, paymentId);
  requireMember(actor);
  return payment.slip_path ? signedSlipUrl(payment.slip_path) : null;
};

import "server-only";
import { Prisma } from "@/generated/prisma/client";
import {
  parseCallbackBody,
  parsePaidAt,
  parseSenAmount,
  verifySignature,
} from "@/lib/gateway-signature";
import { todayInMalaysia } from "@/lib/dates";
import { toSafeNumber } from "@/lib/money";
import type { Actor } from "../auth";
import { findVisibleLease, requireVisibleLease } from "../access";
import { allocatePayment, lockLease, writeAudit } from "../allocation";
import type { Tx } from "../allocation";
import { forbidden, unprocessable } from "../http";
import { prisma } from "../prisma";

// Online payments (docs/TASK.md section 5): a tenant opens a gateway bill for
// what is due now; only the signed webhook callback can settle it.

type CreatedBill = { billId: string; amountSen: number };

type CallbackResult = { status: number; body: Record<string, unknown> };

type BillView = {
  id: string;
  amountSen: number;
  status: string;
  leaseId: string;
  paidAt: string | null;
};

type DueRow = { due: bigint };

type BillStatusRow = { status: string };

type SettleOutcome = "settled" | "failed" | "noop";

type ValidCallback =
  | { billId: string; paid: false }
  | {
      billId: string;
      paid: true;
      amountSen: number;
      paidAt: Date;
      transactionId: string | null;
    };

const GATEWAY_BILL_UNIQUE = "payments_gateway_bill_id_key";

// Concurrent deliveries of one callback queue on the lease lock; give them
// room beyond Prisma's 2 s / 5 s defaults instead of failing with a 500.
const TX_OPTIONS = { maxWait: 10_000, timeout: 15_000 };

const OK: CallbackResult = { status: 200, body: { ok: true } };

const reply = (status: number, error: string): CallbackResult => ({
  status,
  body: { error },
});

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null;

// The pg driver adapter reports a unique violation as P2002 (model query) or
// P2010 (raw query), with the Postgres code and index under
// meta.driverAdapterError.cause. Only OUR constraint counts as "already done".
const isGatewayBillUniqueViolation = (error: unknown): boolean => {
  if (!(error instanceof Prisma.PrismaClientKnownRequestError)) {
    return false;
  }
  const adapterError = error.meta?.driverAdapterError;
  const cause = isRecord(adapterError) ? adapterError.cause : undefined;
  if (!isRecord(cause) || cause.originalCode !== "23505") {
    return false;
  }
  const constraint = cause.constraint;
  return isRecord(constraint) && constraint.index === GATEWAY_BILL_UNIQUE;
};

// Unpaid amount of the lease's invoices due on or before `today` (a Malaysia
// calendar date). Allocations never exceed an invoice (trigger), but
// greatest(…, 0) keeps the sum honest even so.
const amountDueNow = async (
  tx: Tx,
  leaseId: string,
  today: string,
): Promise<bigint> => {
  const rows = await tx.$queryRaw<DueRow[]>`
    SELECT coalesce(sum(greatest(i.amount_sen - coalesce(a.allocated, 0), 0)), 0)::bigint AS due
      FROM public.invoices i
      LEFT JOIN (
        SELECT invoice_id, sum(amount_sen) AS allocated
          FROM public.payment_allocations
         GROUP BY invoice_id
      ) a ON a.invoice_id = i.id
     WHERE i.lease_id = ${leaseId}::uuid
       AND i.due_date <= ${today}::date`;
  return BigInt(rows[0]?.due ?? 0n);
};

/** POST /api/leases/:leaseId/gateway-bills — the lease's own tenant only. */
export const createGatewayBill = async (
  actor: Actor,
  leaseId: string,
  now: Date = new Date(),
): Promise<CreatedBill> => {
  // 404 first (other org / other tenant / bad id), then 403 for staff/manager.
  const lease = await requireVisibleLease(actor, leaseId);
  if (actor.kind !== "tenant" || lease.tenant_id !== actor.tenantId) {
    throw forbidden();
  }
  const today = todayInMalaysia(now);
  return prisma.$transaction(async (tx) => {
    await lockLease(tx, lease.id);
    const due = await amountDueNow(tx, lease.id, today);
    if (due <= 0n) {
      throw unprocessable("Nothing is due");
    }
    // id comes from the DB default: 'bill_' + 32 random hex (unguessable).
    const bill = await tx.gateway_bills.create({
      data: {
        org_id: lease.org_id,
        lease_id: lease.id,
        amount_sen: due,
        created_by: actor.userId,
      },
      select: { id: true, amount_sen: true },
    });
    return { billId: bill.id, amountSen: toSafeNumber(bill.amount_sen) };
  }, TX_OPTIONS);
};

/** The bill, only if its lease is visible to the actor. Read-only. */
export const getBillForActor = async (
  actor: Actor,
  billId: string,
): Promise<BillView | null> => {
  const bill = await prisma.gateway_bills.findFirst({
    where: { id: billId, org_id: actor.orgId },
  });
  if (!bill) {
    return null;
  }
  const lease = await findVisibleLease(actor, bill.lease_id);
  if (!lease) {
    return null;
  }
  return {
    id: bill.id,
    amountSen: toSafeNumber(bill.amount_sen),
    status: bill.status,
    leaseId: bill.lease_id,
    paidAt: bill.paid_at ? bill.paid_at.toISOString() : null,
  };
};

// Field validation, run only AFTER the signature has been verified.
const validateFields = (
  fields: Record<string, string>,
): ValidCallback | string => {
  const billId = fields.id;
  if (!billId) {
    return "Missing id";
  }
  if (fields.paid === "false") {
    return { billId, paid: false };
  }
  if (fields.paid !== "true") {
    return "paid must be true or false";
  }
  const amountSen = parseSenAmount(fields.paid_amount ?? "");
  if (amountSen === null) {
    return "Invalid paid_amount";
  }
  const paidAt = parsePaidAt(fields.paid_at ?? "");
  if (paidAt === null) {
    return "Invalid paid_at";
  }
  return {
    billId,
    paid: true,
    amountSen,
    paidAt,
    transactionId: fields.transaction_id || null,
  };
};

// Applies a verified, validated callback. Lock order matches every other
// money path: lease row first, then the bill row. Under the lease lock the
// bill's status is re-read, so a concurrent duplicate sees 'paid' and no-ops.
const applyCallback = async (
  callback: ValidCallback,
  bill: { org_id: string; lease_id: string; amount_sen: bigint },
): Promise<SettleOutcome> =>
  prisma.$transaction(async (tx) => {
    await lockLease(tx, bill.lease_id);
    const rows = await tx.$queryRaw<BillStatusRow[]>`
      SELECT status FROM public.gateway_bills
       WHERE id = ${callback.billId} FOR UPDATE`;
    const status = rows[0]?.status;

    if (!callback.paid) {
      if (status !== "pending") {
        // failed: repeat delivery. paid: late/out-of-order — never goes back.
        return "noop";
      }
      await tx.gateway_bills.update({
        where: { id: callback.billId },
        data: { status: "failed" },
      });
      return "failed";
    }

    if (status === "paid") {
      return "noop";
    }
    await tx.gateway_bills.update({
      where: { id: callback.billId },
      data: {
        status: "paid",
        paid_at: callback.paidAt,
        transaction_id: callback.transactionId,
      },
    });
    // payments.gateway_bill_id is UNIQUE: even if this point were reached
    // twice, the second insert fails with 23505 and its transaction rolls back.
    const payment = await tx.payments.create({
      data: {
        org_id: bill.org_id,
        lease_id: bill.lease_id,
        amount_sen: bill.amount_sen,
        method: "online",
        status: "approved",
        received_at: callback.paidAt,
        gateway_bill_id: callback.billId,
      },
      select: { id: true },
    });
    await allocatePayment(tx, payment.id);
    await writeAudit(tx, {
      orgId: bill.org_id,
      actorId: null,
      action: "payment.online_settled",
      entityId: payment.id,
      details: {
        billId: callback.billId,
        amountSen: toSafeNumber(bill.amount_sen),
        transactionId: callback.transactionId,
      },
    });
    return "settled";
  }, TX_OPTIONS);

/**
 * POST /api/webhooks/gateway. Takes the raw x-www-form-urlencoded body.
 * Never logs the key or the payload.
 */
export const processGatewayCallback = async (
  rawBody: string,
  key: string,
): Promise<CallbackResult> => {
  // 1. Signature before anything else: an unsigned body tells us nothing.
  const parsed = parseCallbackBody(rawBody);
  if (!parsed.ok || !verifySignature(parsed.fields, key)) {
    return reply(401, "Invalid signature");
  }

  // 2. Shape of the signed fields.
  const callback = validateFields(parsed.fields);
  if (typeof callback === "string") {
    return reply(400, callback);
  }

  // 3. The bill. lease_id and amount_sen are immutable (trigger), so reading
  //    them outside the transaction is safe; status is re-read under lock.
  const bill = await prisma.gateway_bills.findUnique({
    where: { id: callback.billId },
    select: { org_id: true, lease_id: true, amount_sen: true },
  });
  if (!bill) {
    return reply(404, "Unknown bill");
  }
  if (callback.paid && BigInt(callback.amountSen) !== bill.amount_sen) {
    return reply(422, "paid_amount does not match the bill");
  }

  // 4. The effect, exactly once.
  try {
    await applyCallback(callback, bill);
  } catch (error) {
    if (isGatewayBillUniqueViolation(error)) {
      // Another delivery created this bill's payment first: already done.
      return OK;
    }
    throw error;
  }
  return OK;
};
import "server-only";
import { BUSINESS_TIME_ZONE, isYearMonth, monthsBetween } from "@/lib/dates";
import { toSafeNumber } from "@/lib/money";
import { requireMember } from "../access";
import type { Actor } from "../auth";
import { badRequest } from "../http";
import { prisma } from "../prisma";

// Collections report: approved payments per Malaysia calendar month of
// received_at, one row per month in the range (zeros included).

const MAX_MONTHS = 120;

export type CollectionsRow = { month: string; collectedSen: number };

type CollectionsDbRow = { month: string; collected: bigint };

/**
 * GET /api/reports/collections?from=YYYY-MM&to=YYYY-MM. Staff and managers.
 * Month boundaries are Malaysia midnight: each month is the instant range
 * [YYYY-MM-01 00:00 MYT, next month 00:00 MYT), so a payment at
 * 2026-03-01 00:30 MYT (2026-02-28T16:30Z) counts in March. A range join
 * (not date_trunc on the column) lets the (org_id, status, received_at)
 * index serve the query.
 */
export const collectionsReport = async (
  actor: Actor,
  from: unknown,
  to: unknown,
): Promise<CollectionsRow[]> => {
  requireMember(actor);
  if (!isYearMonth(from) || !isYearMonth(to)) {
    throw badRequest("from and to must be months written as YYYY-MM");
  }
  if (from > to) {
    throw badRequest("from must not be after to");
  }
  const months = monthsBetween(from, to);
  if (months.length > MAX_MONTHS) {
    throw badRequest(`Range is limited to ${MAX_MONTHS} months`);
  }

  const rows = await prisma.$queryRaw<CollectionsDbRow[]>`
    SELECT to_char(m.month_start, 'YYYY-MM') AS month,
           coalesce(sum(p.amount_sen), 0)::bigint AS collected
      FROM generate_series(
             ${`${from}-01`}::timestamp,
             ${`${to}-01`}::timestamp,
             interval '1 month'
           ) AS m(month_start)
      LEFT JOIN public.payments p
        ON p.org_id = ${actor.orgId}::uuid
       AND p.status = 'approved'
       AND p.received_at >= (m.month_start AT TIME ZONE ${BUSINESS_TIME_ZONE})
       AND p.received_at < ((m.month_start + interval '1 month') AT TIME ZONE ${BUSINESS_TIME_ZONE})
     GROUP BY m.month_start
     ORDER BY m.month_start`;

  return rows.map((row) => ({
    month: row.month,
    collectedSen: toSafeNumber(BigInt(row.collected)),
  }));
};

-- =============================================================================
-- 2/4 Integrity triggers: defence in depth. The app (Prisma, connected as the
-- table owner, which bypasses RLS) is the first line; these make the important
-- money invariants hold even if app code has a bug.
--
-- All functions live in `private` (not exposed by PostgREST) with an empty
-- search_path, so every name is schema-qualified and cannot be hijacked.
-- Errors use SQLSTATE 23514 (check_violation) or 55000 for illegal state
-- transitions, so the app can map them.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- audit_log is append-only for EVERY role (service_role and the owner too):
-- row triggers stop UPDATE/DELETE, a statement trigger stops TRUNCATE.
-- -----------------------------------------------------------------------------
create function private.audit_log_append_only()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'audit_log is append-only (% refused)', tg_op
    using errcode = '42501';
end;
$$;

create trigger audit_log_no_update_delete
  before update or delete on public.audit_log
  for each row execute function private.audit_log_append_only();

create trigger audit_log_no_truncate
  before truncate on public.audit_log
  for each statement execute function private.audit_log_append_only();

-- -----------------------------------------------------------------------------
-- payments
--   INSERT: starts as pending_verification or approved (online: approved only);
--           an online payment must match its bill's lease and amount.
--   UPDATE: identity and money fields are immutable; status only moves forward:
--             pending_verification -> approved | rejected
--             approved             -> voided
--             rejected, voided     -> (terminal)
--           unapplied_sen + allocations may never exceed amount_sen.
--   DELETE: never. Payments are append-only; a void is a status change.
-- -----------------------------------------------------------------------------
create function private.payments_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_bill public.gateway_bills%rowtype;
  v_allocated bigint;
begin
  if tg_op = 'DELETE' then
    raise exception 'payments are never deleted (void instead)' using errcode = '42501';
  end if;

  if tg_op = 'INSERT' then
    if new.status not in ('pending_verification', 'approved') then
      raise exception 'a new payment must be pending_verification or approved, not %', new.status
        using errcode = '23514';
    end if;
    if new.method = 'online' then
      if new.status <> 'approved' then
        raise exception 'an online payment is created approved (by the webhook)' using errcode = '23514';
      end if;
      select * into v_bill from public.gateway_bills where id = new.gateway_bill_id;
      if v_bill.lease_id is distinct from new.lease_id or v_bill.amount_sen <> new.amount_sen then
        raise exception 'online payment must match its gateway bill (lease and amount)'
          using errcode = '23514';
      end if;
    end if;
    return new;
  end if;

  -- UPDATE
  if new.org_id <> old.org_id
     or new.lease_id <> old.lease_id
     or new.amount_sen <> old.amount_sen
     or new.method <> old.method
     or new.received_at <> old.received_at
     or new.gateway_bill_id is distinct from old.gateway_bill_id
     or new.slip_path is distinct from old.slip_path
     or new.recorded_by is distinct from old.recorded_by
     or new.created_at <> old.created_at then
    raise exception 'payment % : only status, decision fields and unapplied_sen may change', old.id
      using errcode = '55000';
  end if;

  if new.status <> old.status and not (
       (old.status = 'pending_verification' and new.status in ('approved', 'rejected'))
    or (old.status = 'approved' and new.status = 'voided')
  ) then
    raise exception 'payment % : illegal status change % -> %', old.id, old.status, new.status
      using errcode = '55000';
  end if;

  if new.unapplied_sen <> old.unapplied_sen then
    select coalesce(sum(amount_sen), 0) into v_allocated
      from public.payment_allocations where payment_id = new.id;
    if v_allocated + new.unapplied_sen > new.amount_sen then
      raise exception 'payment % : allocated % + unapplied % exceeds amount %',
        new.id, v_allocated, new.unapplied_sen, new.amount_sen using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;

create trigger payments_guard
  before insert or update or delete on public.payments
  for each row execute function private.payments_guard();

-- -----------------------------------------------------------------------------
-- gateway_bills: pending -> paid | failed, failed -> paid; paid is terminal
-- (a late paid=false never un-pays a bill). lease and amount are immutable.
-- Also keeps updated_at current.
-- -----------------------------------------------------------------------------
create function private.gateway_bills_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.id <> old.id
     or new.org_id <> old.org_id
     or new.lease_id <> old.lease_id
     or new.amount_sen <> old.amount_sen then
    raise exception 'gateway bill % : id, org, lease and amount are immutable', old.id
      using errcode = '55000';
  end if;

  if new.status <> old.status and not (
       (old.status = 'pending' and new.status in ('paid', 'failed'))
    or (old.status = 'failed' and new.status = 'paid')
  ) then
    raise exception 'gateway bill % : illegal status change % -> %', old.id, old.status, new.status
      using errcode = '55000';
  end if;

  new.updated_at := now();
  return new;
end;
$$;

create trigger gateway_bills_guard
  before update on public.gateway_bills
  for each row execute function private.gateway_bills_guard();

-- -----------------------------------------------------------------------------
-- payment_allocations
--   INSERT/UPDATE: the payment must be approved; invoice and payment must be on
--     the same lease; sum per invoice <= invoice amount; sum per payment <=
--     payment amount. The invoice and payment rows are locked first
--     (FOR NO KEY UPDATE: does not conflict with the FK's KEY SHARE locks, so no
--     deadlock), so two concurrent transactions allocating to the same invoice
--     are serialized and the second one's sum sees the first one's rows
--     (READ COMMITTED takes a fresh snapshot per statement).
--   DELETE: only when the payment is voided (void = set status, then delete its
--     allocations, in one transaction).
-- -----------------------------------------------------------------------------
create function private.payment_allocations_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_payment public.payments%rowtype;
  v_invoice public.invoices%rowtype;
  v_sum bigint;
begin
  if tg_op = 'DELETE' then
    select * into v_payment from public.payments where id = old.payment_id;
    if v_payment.status <> 'voided' then
      raise exception 'allocations of payment % can only be removed after it is voided', old.payment_id
        using errcode = '55000';
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' and (new.payment_id <> old.payment_id
                           or new.invoice_id <> old.invoice_id
                           or new.org_id <> old.org_id) then
    raise exception 'allocation % : payment, invoice and org are immutable', old.id
      using errcode = '55000';
  end if;

  select * into v_invoice from public.invoices where id = new.invoice_id for no key update;
  select * into v_payment from public.payments where id = new.payment_id for no key update;

  if v_payment.status <> 'approved' then
    raise exception 'only approved payments can be allocated (payment % is %)', v_payment.id, v_payment.status
      using errcode = '55000';
  end if;
  if v_invoice.lease_id <> v_payment.lease_id then
    raise exception 'payment and invoice belong to different leases' using errcode = '23514';
  end if;

  select coalesce(sum(amount_sen), 0) into v_sum
    from public.payment_allocations where invoice_id = new.invoice_id;
  if v_sum > v_invoice.amount_sen then
    raise exception 'invoice % over-allocated: % > %', v_invoice.id, v_sum, v_invoice.amount_sen
      using errcode = '23514';
  end if;

  select coalesce(sum(amount_sen), 0) into v_sum
    from public.payment_allocations where payment_id = new.payment_id;
  if v_sum > v_payment.amount_sen then
    raise exception 'payment % over-allocated: % > %', v_payment.id, v_sum, v_payment.amount_sen
      using errcode = '23514';
  end if;

  return new;
end;
$$;

-- AFTER: the sums must include the row just written.
create trigger payment_allocations_guard
  after insert or update or delete on public.payment_allocations
  for each row execute function private.payment_allocations_guard();

-- -----------------------------------------------------------------------------
-- memberships.user_id / tenants.user_id must name a real auth user. This stands
-- in for a FK to auth.users, which Prisma introspection cannot handle (it
-- refuses cross-schema FKs). Trade-off: deleting an auth user does not cascade;
-- users are not deleted in this app.
-- -----------------------------------------------------------------------------
create function private.require_auth_user()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.user_id is not null
     and not exists (select 1 from auth.users u where u.id = new.user_id) then
    raise exception '%.user_id % is not an auth user', tg_table_name, new.user_id
      using errcode = '23503';
  end if;
  return new;
end;
$$;

create trigger memberships_require_auth_user
  before insert or update of user_id on public.memberships
  for each row execute function private.require_auth_user();

create trigger tenants_require_auth_user
  before insert or update of user_id on public.tenants
  for each row execute function private.require_auth_user();
