});
const deliver = (f: Record<string, string>) => processGatewayCallback(signed(f), KEY);
const NOW = new Date("2026-06-15T00:00:00Z");
const leaseSums = async (leaseId: string) => {
  const inv = await prisma.invoices.aggregate({ where: { lease_id: leaseId }, _sum: { amount_sen: true } });
  const al = await prisma.payment_allocations.aggregate({
    where: { invoices: { lease_id: leaseId } },
    _sum: { amount_sen: true },
  });
  return { invoiced: inv._sum.amount_sen ?? 0n, allocated: al._sum.amount_sen ?? 0n };
};

