import { describe, expect, test } from "vitest";
import { z } from "zod";
import { computeSignature } from "@/lib/gateway-signature";
import { calendarDateFromDb } from "@/lib/dates";
import { HttpError } from "@/lib/server/http";
import { prisma } from "@/lib/server/prisma";
import { getLeaseDetail, dashboardStats } from "@/lib/server/services/leases";
import {
  approvePayment,
  recordPayment,
  rejectPayment,
  voidPayment,
} from "@/lib/server/services/payments";
