  createGatewayBill,
  processGatewayCallback,
} from "@/lib/server/services/gateway";
import { collectionsReport } from "@/lib/server/services/reports";
import { createFixture } from "./helpers/fixtures";

const KEY = process.env.GATEWAY_X_SIGNATURE_KEY ?? "";
const AT = "2026-01-15T10:00:00+08:00";
const cash = (amountSen: number, receivedAt = AT) => ({
  amountSen,
  method: "cash" as const,
  receivedAt,
});
const st = async (p: Promise<unknown>): Promise<number> => {
  try {
    await p;
    return 200;
  } catch (e) {
    if (e instanceof HttpError) return e.status;
    if (e instanceof z.ZodError) return 400;
    console.log("UNEXPECTED", e instanceof Error ? e.message : e);
    return 500;
  }
};
const signed = (f: Record<string, string>) =>
  new URLSearchParams({ ...f, x_signature: computeSignature(f, KEY) }).toString();
const paid = (id: string, amt: number, at = "2026-02-15 10:00:00 +0800") => ({
  id,
  paid: "true",
  paid_amount: String(amt),
  paid_at: at,
  transaction_id: "TX-1",
  transaction_status: "completed",
});
const failed = (id: string) => ({
  id,
  paid: "false",
  paid_amount: "0",
  paid_at: "2026-02-15 10:00:00 +0800",
  transaction_id: "TX-1",
  transaction_status: "failed",
});
const deliver = (f: Record<string, string>) => processGatewayCallback(signed(f), KEY);
const NOW = new Date("2026-06-15T00:00:00Z");
const leaseSums = async (leaseId: string) => {
  const inv = await prisma.invoices.aggregate({ where: { lease_id: leaseId }, _sum: { amount_sen: true } });
  const al = await prisma.payment_allocations.aggregate({
    where: { invoices: { lease_id: leaseId } },
    _sum: { amount_sen: true },
  });
  return { invoiced: inv._sum.amount_sen ?? 0n, allocated: al._sum.amount_sen ?? 0n };
};

