import { describe, expect, test } from "vitest";
import { z } from "zod";
import { computeSignature } from "@/lib/gateway-signature";
import { HttpError } from "@/lib/server/http";
import { prisma } from "@/lib/server/prisma";
import {
  approvePayment,
  recordPayment,
  rejectPayment,
} from "@/lib/server/services/payments";
import {
  createGatewayBill,
  processGatewayCallback,
} from "@/lib/server/services/gateway";
import { createFixture } from "./helpers/fixtures";

const KEY = process.env.GATEWAY_X_SIGNATURE_KEY ?? "";
const AT = "2026-01-15T10:00:00+08:00";
const cash = (amountSen: number) => ({ amountSen, method: "cash" as const, receivedAt: AT });
const st = async (p: Promise<unknown>): Promise<string> => {
  try {
    await p;
    return "200";
  } catch (e) {
    if (e instanceof HttpError) return String(e.status);
    if (e instanceof z.ZodError) return "400";
    return `500:${e instanceof Error ? e.message.slice(0, 160) : String(e)}`;
  }
};
const signed = (f: Record<string, string>) =>
  new URLSearchParams({ ...f, x_signature: computeSignature(f, KEY) }).toString();
const NOW = new Date("2026-06-15T00:00:00Z");

describe("audit2", () => {
  test("emoji reason", async () => {
    const f = await createFixture();
    const p = await recordPayment(f.staffActor, f.leaseId, cash(1000));
    console.log("emoji reason:", await st(rejectPayment(f.managerActor, p.id, { reason: "\u{1F600}\u{1F600}\u{1F600}" })));
  });

  test("40 concurrent webhooks", async () => {
    const f = await createFixture();
    const bill = await createGatewayBill(f.tenantActor, f.leaseId, NOW);
    const fields = {
      id: bill.billId, paid: "true", paid_amount: String(bill.amountSen),
      paid_at: "2026-02-15 10:00:00 +0800", transaction_id: "TX-9", transaction_status: "completed",
    };
    const rs = await Promise.all(Array.from({ length: 40 }, () =>
      processGatewayCallback(signed(fields), KEY).then((r) => String(r.status)).catch((e: unknown) => `500:${e instanceof Error ? e.message.slice(0, 160) : ""}`)));
    const counts: Record<string, number> = {};
    for (const r of rs) counts[r] = (counts[r] ?? 0) + 1;
    console.log("40 webhooks", counts);
    expect(await prisma.payments.count({ where: { gateway_bill_id: bill.billId } })).toBe(1);
  }, 120000);

  test("40 concurrent records + approvals", async () => {
    const f = await createFixture();
    const rs = await Promise.all(Array.from({ length: 40 }, (_, i) => st(recordPayment(i % 2 ? f.staffActor : f.managerActor, f.leaseId, cash(10000)))));
    const counts: Record<string, number> = {};
    for (const r of rs) counts[r] = (counts[r] ?? 0) + 1;
    console.log("40 records", counts);
    const pend = await prisma.payments.findMany({ where: { lease_id: f.leaseId, status: "pending_verification" } });
    const ap = await Promise.all(pend.flatMap((p) => [st(approvePayment(f.managerActor, p.id)), st(approvePayment(f.managerActor, p.id))]));
    const c2: Record<string, number> = {};
    for (const r of ap) c2[r] = (c2[r] ?? 0) + 1;
    console.log("double approvals", c2);
    const al = await prisma.payment_allocations.aggregate({ where: { invoices: { lease_id: f.leaseId } }, _sum: { amount_sen: true } });
    console.log("allocated", al._sum.amount_sen);
    expect((al._sum.amount_sen ?? 0n) <= 300000n).toBe(true);
  }, 120000);
});

